import re


_PREC = {"+": 1, "-": 1, "*": 2, "/": 2, "%": 2, "u": 3, "^": 4}


def _apply(op: str, a: int, b: int) -> int:
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if op == "^":
        if b < 0:
            raise ValueError
        return a ** b
    if b == 0:
        raise ZeroDivisionError
    q = abs(a) // abs(b)
    if (a < 0) != (b < 0):
        q = -q
    return q if op == "/" else a - b * q


def calc(expr: str) -> int | str:
    tokens = re.findall(r"[0-9]+|[-+*/%^()]", expr)
    output = []
    ops = []
    expect_operand = True
    for tok in tokens:
        if tok[0].isdigit():
            output.append(int(tok))
            expect_operand = False
        elif tok == "(":
            ops.append(tok)
            expect_operand = True
        elif tok == ")":
            while ops and ops[-1] != "(":
                output.append(ops.pop())
            if ops:
                ops.pop()
            expect_operand = False
        elif expect_operand and tok == "-":
            ops.append("u")
        else:
            prec = _PREC[tok]
            right = tok == "^"
            while ops and ops[-1] != "(":
                top = _PREC[ops[-1]]
                if top > prec or (top == prec and not right):
                    output.append(ops.pop())
                else:
                    break
            ops.append(tok)
            expect_operand = True
    while ops:
        output.append(ops.pop())

    stack = []
    try:
        for item in output:
            if isinstance(item, int):
                stack.append(item)
            elif item == "u":
                stack.append(-stack.pop())
            else:
                b = stack.pop()
                a = stack.pop()
                stack.append(_apply(item, a, b))
    except (ZeroDivisionError, ValueError):
        return "error"
    return stack[0]
